import type { StealthJarInvite } from '@honey-wallet/api-client';
import {
  type DkgRound1Message,
  type DkgRound2Message,
  dkgFinish,
  dkgRound2,
  dkgStart,
  type StealthJarKey,
  type Threshold,
} from '@honey-wallet/keyring';
import { getRandomBytes } from 'expo-crypto';
import { api } from '@/lib/api';
import { backendSessionToken } from '@/lib/backend-session';
import { getItemAsync, setItemAsync } from '@/lib/secure-store';

/**
 * Stealth jars (private group jars): FROST threshold key over a fresh NEAR implicit
 * account, generated by DKG through Honey's blind relay. Off unless
 * EXPO_PUBLIC_STEALTH_JARS=1. No UI is wired yet; public jars keep using Sputnik DAO.
 */
export const stealthJarsEnabled = process.env.EXPO_PUBLIC_STEALTH_JARS === '1';

const ROUND_DKG_1 = 1;
const ROUND_DKG_2 = 2;
const POLL_MS = 1500;
const TIMEOUT_MS = 10 * 60 * 1000;
const storageKey = (accountId: string) => `stealth-jar.${accountId}`;

function token() {
  if (!stealthJarsEnabled) throw new Error('Stealth jars are not enabled');
  const value = backendSessionToken();
  if (!value) throw new Error('Sign in to use stealth jars');
  return value;
}

async function collect<T>(
  invite: StealthJarInvite,
  round: number,
  want: number,
  signal?: AbortSignal,
): Promise<T[]> {
  const deadline = Date.now() + TIMEOUT_MS;
  while (Date.now() < deadline) {
    signal?.throwIfAborted();
    const messages = await api.stealthJarReceive(token(), invite, round);
    if (messages.length >= want) return messages.map((m) => JSON.parse(m.data) as T);
    await new Promise((r) => setTimeout(r, POLL_MS));
  }
  throw new Error('Other members did not finish in time');
}

/** Creator: opens a session; share `invite` with members out of band (QR / link). */
export async function createStealthJarSession(members: number) {
  return api.stealthJarCreate(token(), members);
}

/**
 * Runs this device's half of the DKG and stores the resulting share in the keychain.
 * Show `transcript` to members so they can compare it out of band.
 */
export async function runStealthJarDkg(
  invite: StealthJarInvite,
  threshold: Threshold,
  signal?: AbortSignal,
): Promise<StealthJarKey> {
  const { memberIndex } = await api.stealthJarJoin(token(), invite);
  const { state, message } = dkgStart(memberIndex, threshold, getRandomBytes);
  await api.stealthJarSend(token(), invite, ROUND_DKG_1, 0, JSON.stringify(message));
  const round1 = await collect<DkgRound1Message>(invite, ROUND_DKG_1, threshold.max, signal);
  for (const box of dkgRound2(state, round1, getRandomBytes))
    await api.stealthJarSend(token(), invite, ROUND_DKG_2, box.to, JSON.stringify(box));
  const round2 = await collect<DkgRound2Message>(invite, ROUND_DKG_2, threshold.max - 1, signal);
  const jar = dkgFinish(state, round1, round2);
  await setItemAsync(storageKey(jar.accountId), JSON.stringify(jar));
  return jar;
}

export async function loadStealthJar(accountId: string): Promise<StealthJarKey | null> {
  const raw = await getItemAsync(storageKey(accountId));
  return raw ? (JSON.parse(raw) as StealthJarKey) : null;
}
